const req = $input.first().json;
const p = req.body || {};
const token = (req.headers && req.headers['x-ismas-token']) || '';
const valid = token !== '' && token === $env.ISMAS_AGENT_TOKEN
              && p.schema === 'ismas.v1' && !!p.server;

const RANK = { info: 0, warning: 1, error: 2, critical: 3 };
const events = Array.isArray(p.events) ? p.events.slice(0, 50) : [];
const maxLevel = events.reduce(
  (m, e) => ((RANK[e.level] ?? 0) > (RANK[m] ?? 0) ? e.level : m), 'info');

// New error/critical events the AI hasn't analyzed yet
const fresh = events.filter(e =>
  (RANK[e.level] ?? 0) >= 2 && (p.type === 'critical' || !e.already_alerted));

// Fingerprint of "this problem" for dedup (numbers / hashes stripped)
const norm = s => String(s).toLowerCase()
  .replace(/<(ip|email):\w+>/g, '<$1>')
  .replace(/\d+(\.\d+)?/g, 'N')
  .slice(0, 160);
const sigSrc = [...new Set(fresh.map(e => `${p.server}|${e.source}|${e.level}|${norm(e.message)}`))]
  .sort().join('||');
let h = 5381;
for (const c of sigSrc) h = ((h << 5) + h + c.charCodeAt(0)) >>> 0;

return [{
  json: {
    valid,
    server: p.server || null,
    type: p.type || null,
    sent_at: p.sent_at || null,
    max_level: maxLevel,
    needs_ai: valid && fresh.length > 0,
    signature: sigSrc ? 'sig_' + h.toString(16) : null,
    fresh_events: fresh,
    payload: p,
  },
}];

const v = $('Validate').first().json;
const ctx = $input.first().json;
const p = v.payload;

const system = `You are ISMAS, a senior SRE assistant analyzing server monitoring data.
Respond ONLY with a single json object, no markdown, using exactly this shape:
{
  "severity": "info" | "low" | "medium" | "high" | "critical",
  "title": "short headline, max 80 chars",
  "root_cause": "2-3 sentences. Cite the evidence (server, source, message, time).",
  "affected_servers": ["server names"],
  "correlated": true | false,
  "fix_steps": ["up to 4 short imperative steps, include shell commands when useful"],
  "confidence": 0.0 to 1.0,
  "needs_human": true | false
}
Rules:
- Use ONLY the data provided. Never invent log lines, servers or numbers.
- A server whose seconds_since_last_report is above 60 may be down or unreachable.
- When events on several servers are related, the earliest failure is usually the root cause; set "correlated": true.
- If evidence is weak or ambiguous, say so in root_cause and lower confidence.
- Severity guide: critical = service down or data at risk; high = users affected now;
  medium = degraded or failing intermittently; low = minor; info = nothing actionable.
Example output:
{"severity":"high","title":"Web app failing: database refusing connections","root_cause":"sim-web /db returns 'Connection refused' since 10:42 while sim-db has not reported for 75s. The database is likely down.","affected_servers":["sim-db","sim-web"],"correlated":true,"fix_steps":["docker start sim-db","Check /var/log/mysql/error.log on sim-db"],"confidence":0.85,"needs_human":true}`;

const data = {
  reporting_server: v.server,
  payload_type: v.type,                 // "critical" = sent immediately by the agent
  sent_at: v.sent_at,
  metrics: p.metrics,
  processes: p.processes,
  new_events: v.fresh_events,
  recent_errors_all_servers_last_5min: ctx.recent_events,
  server_status: ctx.servers,
};

return [{
  json: {
    body: {
      model: 'deepseek-chat',
      temperature: 0.2,
      max_tokens: 800,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: system },
        { role: 'user', content: 'Analyze this monitoring data and return the json object.\n' + JSON.stringify(data) },
      ],
    },
  },
}];

const v = $('Validate').first().json;
const res = $input.first().json;
const content = res?.choices?.[0]?.message?.content || '';

let ai = null;
try { ai = JSON.parse(content); } catch (e) { ai = null; }

// Fallback: never lose an alert just because the AI answer was broken/empty
if (!ai || typeof ai !== 'object') {
  ai = {
    severity: v.max_level === 'critical' ? 'high' : 'medium',
    title: `Unanalyzed ${v.max_level} events on ${v.server}`,
    root_cause: 'AI response could not be parsed. First event: ' +
      (v.fresh_events[0]?.message || 'n/a'),
    affected_servers: [v.server],
    fix_steps: [],
    confidence: 0,
    needs_human: true,
    parse_failed: true,
  };
}

const SEV = ['info', 'low', 'medium', 'high', 'critical'];
const severity = SEV.includes(String(ai.severity).toLowerCase())
  ? String(ai.severity).toLowerCase() : 'medium';
const confidence = Math.max(0, Math.min(1, Number(ai.confidence) || 0));
const servers = Array.isArray(ai.affected_servers) && ai.affected_servers.length
  ? ai.affected_servers.map(String) : [v.server];
const steps = Array.isArray(ai.fix_steps) ? ai.fix_steps.slice(0, 4).map(String) : [];
const title = String(ai.title || 'Untitled incident').slice(0, 120);
const cause = String(ai.root_cause || '').slice(0, 1500);

// Telegram (HTML parse mode) -- escape &, <, >
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const icon = { critical: '🔴', high: '🟠', medium: '🟡', low: '🔵', info: '⚪' }[severity];
let text = `${icon} <b>${severity.toUpperCase()} — ${esc(title)}</b>\n`
  + `Servers: ${esc(servers.join(', '))}${ai.correlated ? ' (correlated)' : ''}\n\n`
  + `<b>Cause:</b> ${esc(cause)}`;
if (steps.length) text += `\n\n<b>Fix:</b>\n` + steps.map((s, i) => `${i + 1}) ${esc(s)}`).join('\n');
text += `\n\nConfidence: ${confidence.toFixed(2)}${ai.needs_human ? ' · needs human' : ''}`;

return [{
  json: {
    signature: v.signature,
    severity,
    title,
    root_cause: cause,
    affected_servers: servers,
    fix_steps: steps,
    confidence,
    should_alert: ['high', 'critical'].includes(severity),
    telegram_text: text.slice(0, 3900),
    ai_raw: ai,
  },
}];
